-- V0001: tenancy baseline (Phase 1).
-- Tables: subjects, organizations, memberships, workspaces, workspace_memberships, api_keys, audit_events.
-- Rules: docs/data/data-model.md, ADR-0006 (isolation), ADR-0008 (identity, API keys), ADR-0010 (roles), ADR-0013.
--
-- IDs are UUIDv7 generated by the application (Guid.CreateVersion7); PostgreSQL 17 has no uuidv7().
-- Every tenant-owned table has organization_id, RLS ENABLE + FORCE, and the tenant_isolation policy.
-- FORCE also binds the table owner (aiep_migrator), so SECURITY DEFINER functions owned by it are still subject to
-- RLS. The bootstrap functions at the end of this file handle that explicitly.
-- Applied by Aiep.Migrator inside a single transaction; do not add BEGIN/COMMIT here.

-- ---------------------------------------------------------------------------------------------------------------
-- subjects: internal identities. NOT tenant-owned (one person can belong to many organizations).
-- Access rule: services can SELECT only themselves and members of the current organization; they cannot write.
-- Rows are created and refreshed only through aiep.resolve_subject(), called after token validation.
-- ---------------------------------------------------------------------------------------------------------------
CREATE TABLE aiep.subjects (
    id                uuid        PRIMARY KEY,
    issuer            text        NOT NULL CHECK (length(issuer) BETWEEN 1 AND 512),
    external_subject  text        NOT NULL CHECK (length(external_subject) BETWEEN 1 AND 255),
    display_name      text        NULL     CHECK (length(display_name) <= 200),
    email             text        NULL     CHECK (length(email) <= 320),
    created_at        timestamptz NOT NULL DEFAULT now(),
    updated_at        timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT subjects_issuer_external_subject_uk UNIQUE (issuer, external_subject)
);

-- ---------------------------------------------------------------------------------------------------------------
-- organizations: the tenant. RLS compares id (not organization_id) with the context.
-- Created only through aiep.create_organization(); services may UPDATE (name, status) but not INSERT or DELETE.
-- ---------------------------------------------------------------------------------------------------------------
CREATE TABLE aiep.organizations (
    id          uuid        PRIMARY KEY,
    name        text        NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 200),
    status      text        NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'deleting')),
    created_at  timestamptz NOT NULL DEFAULT now(),
    created_by  uuid        NULL REFERENCES aiep.subjects (id),
    updated_at  timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------------------------------------------
-- memberships: a subject's organization role (ADR-0010).
-- ---------------------------------------------------------------------------------------------------------------
CREATE TABLE aiep.memberships (
    id               uuid        PRIMARY KEY,
    organization_id  uuid        NOT NULL REFERENCES aiep.organizations (id),
    subject_id       uuid        NOT NULL REFERENCES aiep.subjects (id),
    org_role         text        NOT NULL CHECK (org_role IN ('Owner', 'Admin', 'Auditor', 'Member')),
    status           text        NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended')),
    created_at       timestamptz NOT NULL DEFAULT now(),
    created_by       uuid        NULL REFERENCES aiep.subjects (id),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT memberships_org_id_uk      UNIQUE (organization_id, id),
    CONSTRAINT memberships_org_subject_uk UNIQUE (organization_id, subject_id)
);
-- Supports the subjects visibility policy (subject -> organizations it belongs to).
CREATE INDEX memberships_subject_idx ON aiep.memberships (subject_id, organization_id);

-- ---------------------------------------------------------------------------------------------------------------
-- workspaces
-- ---------------------------------------------------------------------------------------------------------------
CREATE TABLE aiep.workspaces (
    id               uuid        PRIMARY KEY,
    organization_id  uuid        NOT NULL REFERENCES aiep.organizations (id),
    slug             text        NOT NULL CHECK (slug ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$'),
    name             text        NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 200),
    status           text        NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'archived', 'deleting')),
    archived_at      timestamptz NULL,
    created_at       timestamptz NOT NULL DEFAULT now(),
    created_by       uuid        NULL REFERENCES aiep.subjects (id),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT workspaces_org_id_uk   UNIQUE (organization_id, id),
    CONSTRAINT workspaces_org_slug_uk UNIQUE (organization_id, slug),
    CONSTRAINT workspaces_archived_at_ck CHECK ((status = 'archived') = (archived_at IS NOT NULL))
);

-- ---------------------------------------------------------------------------------------------------------------
-- workspace_memberships: workspace role grants (ADR-0010). A grant requires an organization membership in the
-- same organization (composite FK) and disappears with it (cascade).
-- ---------------------------------------------------------------------------------------------------------------
CREATE TABLE aiep.workspace_memberships (
    id               uuid        PRIMARY KEY,
    organization_id  uuid        NOT NULL,
    workspace_id     uuid        NOT NULL,
    subject_id       uuid        NOT NULL,
    workspace_role   text        NOT NULL
        CHECK (workspace_role IN ('WorkspaceAdmin', 'Developer', 'Evaluator', 'Viewer')),
    created_at       timestamptz NOT NULL DEFAULT now(),
    created_by       uuid        NULL REFERENCES aiep.subjects (id),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT workspace_memberships_org_id_uk UNIQUE (organization_id, id),
    CONSTRAINT workspace_memberships_org_ws_subject_uk UNIQUE (organization_id, workspace_id, subject_id),
    CONSTRAINT workspace_memberships_workspace_fk
        FOREIGN KEY (organization_id, workspace_id) REFERENCES aiep.workspaces (organization_id, id),
    CONSTRAINT workspace_memberships_membership_fk
        FOREIGN KEY (organization_id, subject_id) REFERENCES aiep.memberships (organization_id, subject_id)
        ON DELETE CASCADE
);

-- ---------------------------------------------------------------------------------------------------------------
-- api_keys (ADR-0008). Plaintext is aiep_<env>_<key_id>_<secret>; only key_id and HMAC-SHA-256(pepper, secret)
-- are stored. key_id is globally unique because it is looked up before the tenant is known
-- (see aiep.find_api_key). Revocation is a soft update (revoked_at), so services cannot DELETE.
-- owner_subject_id references subjects, not memberships: removing a member must not be blocked by their keys, and
-- the key's permissions are re-checked against the owner's current memberships on every use.
-- ---------------------------------------------------------------------------------------------------------------
CREATE TABLE aiep.api_keys (
    id                uuid        PRIMARY KEY,
    organization_id   uuid        NOT NULL REFERENCES aiep.organizations (id),
    workspace_id      uuid        NULL,
    key_id            text        NOT NULL CHECK (key_id ~ '^[a-z0-9]{16,32}$'),
    secret_hash       bytea       NOT NULL CHECK (octet_length(secret_hash) = 32),
    environment       text        NOT NULL CHECK (environment ~ '^[a-z]{2,10}$'),
    name              text        NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 200),
    owner_subject_id  uuid        NOT NULL REFERENCES aiep.subjects (id),
    permissions       text[]      NOT NULL CHECK (cardinality(permissions) > 0),
    expires_at        timestamptz NULL,
    last_used_at      timestamptz NULL,
    revoked_at        timestamptz NULL,
    revoked_by        uuid        NULL REFERENCES aiep.subjects (id),
    created_at        timestamptz NOT NULL DEFAULT now(),
    created_by        uuid        NULL REFERENCES aiep.subjects (id),
    CONSTRAINT api_keys_key_id_uk UNIQUE (key_id),
    CONSTRAINT api_keys_org_id_uk UNIQUE (organization_id, id),
    CONSTRAINT api_keys_workspace_fk
        FOREIGN KEY (organization_id, workspace_id) REFERENCES aiep.workspaces (organization_id, id)
);

-- ---------------------------------------------------------------------------------------------------------------
-- audit_events: append-only. Services may INSERT and SELECT only; a trigger blocks UPDATE and DELETE even for the
-- owner, so a retention purge must be an explicit, reviewed migration that disables it.
-- workspace_id and target_id deliberately have no foreign keys: audit records must outlive what they describe.
-- No free-form payload column: prompts, outputs and secrets must never be audited (CLAUDE.md, ADR-0012).
-- ---------------------------------------------------------------------------------------------------------------
CREATE TABLE aiep.audit_events (
    id                 uuid        PRIMARY KEY,
    organization_id    uuid        NOT NULL REFERENCES aiep.organizations (id),
    workspace_id       uuid        NULL,
    occurred_at        timestamptz NOT NULL DEFAULT now(),
    actor_type         text        NOT NULL CHECK (actor_type IN ('user', 'api_key', 'service')),
    actor_subject_id   uuid        NULL,
    actor_api_key_id   uuid        NULL,
    action             text        NOT NULL CHECK (action ~ '^[a-z_]+(\.[a-z_]+)+$'),
    target_type        text        NULL     CHECK (length(target_type) <= 64),
    target_id          uuid        NULL,
    outcome            text        NOT NULL CHECK (outcome IN ('success', 'denied', 'failure')),
    reason             text        NULL     CHECK (length(reason) <= 500),
    correlation_id     text        NULL     CHECK (length(correlation_id) <= 128),
    CONSTRAINT audit_events_org_id_uk UNIQUE (organization_id, id)
);
CREATE INDEX audit_events_org_time_idx ON aiep.audit_events (organization_id, occurred_at DESC);

CREATE FUNCTION aiep.audit_events_append_only() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'audit_events is append-only' USING ERRCODE = 'insufficient_privilege';
END;
$$;

CREATE TRIGGER audit_events_append_only
    BEFORE UPDATE OR DELETE ON aiep.audit_events
    FOR EACH ROW EXECUTE FUNCTION aiep.audit_events_append_only();

-- ---------------------------------------------------------------------------------------------------------------
-- Row-level security (ADR-0006). The context is set only with set_config(..., true) inside a transaction.
-- A missing or empty context becomes NULL and matches no rows.
-- ---------------------------------------------------------------------------------------------------------------
ALTER TABLE aiep.organizations         ENABLE ROW LEVEL SECURITY;
ALTER TABLE aiep.organizations         FORCE  ROW LEVEL SECURITY;
ALTER TABLE aiep.memberships           ENABLE ROW LEVEL SECURITY;
ALTER TABLE aiep.memberships           FORCE  ROW LEVEL SECURITY;
ALTER TABLE aiep.workspaces            ENABLE ROW LEVEL SECURITY;
ALTER TABLE aiep.workspaces            FORCE  ROW LEVEL SECURITY;
ALTER TABLE aiep.workspace_memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE aiep.workspace_memberships FORCE  ROW LEVEL SECURITY;
ALTER TABLE aiep.api_keys              ENABLE ROW LEVEL SECURITY;
ALTER TABLE aiep.api_keys              FORCE  ROW LEVEL SECURITY;
ALTER TABLE aiep.audit_events          ENABLE ROW LEVEL SECURITY;
ALTER TABLE aiep.audit_events          FORCE  ROW LEVEL SECURITY;
ALTER TABLE aiep.subjects              ENABLE ROW LEVEL SECURITY;
ALTER TABLE aiep.subjects              FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON aiep.organizations
    USING      (id = nullif(current_setting('app.organization_id', true), '')::uuid)
    WITH CHECK (id = nullif(current_setting('app.organization_id', true), '')::uuid);

CREATE POLICY tenant_isolation ON aiep.memberships
    USING      (organization_id = nullif(current_setting('app.organization_id', true), '')::uuid)
    WITH CHECK (organization_id = nullif(current_setting('app.organization_id', true), '')::uuid);

CREATE POLICY tenant_isolation ON aiep.workspaces
    USING      (organization_id = nullif(current_setting('app.organization_id', true), '')::uuid)
    WITH CHECK (organization_id = nullif(current_setting('app.organization_id', true), '')::uuid);

CREATE POLICY tenant_isolation ON aiep.workspace_memberships
    USING      (organization_id = nullif(current_setting('app.organization_id', true), '')::uuid)
    WITH CHECK (organization_id = nullif(current_setting('app.organization_id', true), '')::uuid);

CREATE POLICY tenant_isolation ON aiep.api_keys
    USING      (organization_id = nullif(current_setting('app.organization_id', true), '')::uuid)
    WITH CHECK (organization_id = nullif(current_setting('app.organization_id', true), '')::uuid);

CREATE POLICY tenant_isolation ON aiep.audit_events
    USING      (organization_id = nullif(current_setting('app.organization_id', true), '')::uuid)
    WITH CHECK (organization_id = nullif(current_setting('app.organization_id', true), '')::uuid);

-- Subjects: yourself, or anyone with a membership in the current organization. The memberships subquery is itself
-- filtered by memberships' tenant policy. Read-only for services (no INSERT/UPDATE/DELETE grant below).
CREATE POLICY subject_visibility ON aiep.subjects
    FOR SELECT TO aiep_api, aiep_worker
    USING (
        id = nullif(current_setting('app.subject_id', true), '')::uuid
        OR EXISTS (
            SELECT 1 FROM aiep.memberships m
            WHERE m.subject_id = subjects.id
              AND m.organization_id = nullif(current_setting('app.organization_id', true), '')::uuid
        )
    );

-- Pre-tenant lookups: run inside SECURITY DEFINER functions owned by aiep_migrator, before any organization is known.
-- aiep_migrator owns these tables and could disable RLS anyway, so these policies give it nothing new; services
-- never connect as aiep_migrator and reach these rows only through the functions' fixed queries.
CREATE POLICY definer_identity_resolution ON aiep.subjects
    FOR ALL TO aiep_migrator USING (true) WITH CHECK (true);

CREATE POLICY definer_api_key_lookup ON aiep.api_keys
    FOR SELECT TO aiep_migrator USING (true);

-- ---------------------------------------------------------------------------------------------------------------
-- Privileges. 01-roles.sh grants SELECT/INSERT/UPDATE/DELETE on every new table to both services by default;
-- narrow that here. The worker does not use control-plane tables yet (Phase 2 grants what it needs, with a reason).
-- ---------------------------------------------------------------------------------------------------------------
REVOKE INSERT, UPDATE, DELETE ON aiep.subjects              FROM aiep_api, aiep_worker;
REVOKE INSERT, DELETE         ON aiep.organizations         FROM aiep_api;
REVOKE DELETE                 ON aiep.workspaces            FROM aiep_api;
REVOKE DELETE                 ON aiep.api_keys              FROM aiep_api;
REVOKE UPDATE, DELETE         ON aiep.audit_events          FROM aiep_api, aiep_worker;
REVOKE INSERT, UPDATE, DELETE ON aiep.organizations, aiep.memberships, aiep.workspaces,
                                 aiep.workspace_memberships, aiep.api_keys
                              FROM aiep_worker;

-- ---------------------------------------------------------------------------------------------------------------
-- Bootstrap functions (SECURITY DEFINER). Each has a fixed search_path, EXECUTE revoked from PUBLIC, and is granted
-- only to aiep_api.
-- ---------------------------------------------------------------------------------------------------------------

-- Map a validated token's (iss, sub) to a subject, creating it on first sign-in and refreshing display data.
-- p_new_id is a UUIDv7 from the application, used only if the subject does not exist yet.
CREATE FUNCTION aiep.resolve_subject(
    p_new_id uuid, p_issuer text, p_external_subject text, p_display_name text, p_email text)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = aiep, pg_temp
AS $$
DECLARE
    v_id uuid;
BEGIN
    -- Fast path: existing subject with unchanged display data needs no write.
    SELECT s.id INTO v_id
    FROM aiep.subjects s
    WHERE s.issuer = p_issuer AND s.external_subject = p_external_subject
      AND s.display_name IS NOT DISTINCT FROM p_display_name
      AND s.email IS NOT DISTINCT FROM p_email;
    IF FOUND THEN
        RETURN v_id;
    END IF;

    INSERT INTO aiep.subjects AS s (id, issuer, external_subject, display_name, email)
    VALUES (p_new_id, p_issuer, p_external_subject, p_display_name, p_email)
    ON CONFLICT (issuer, external_subject) DO UPDATE
        SET display_name = excluded.display_name,
            email        = excluded.email,
            updated_at   = now()
    RETURNING s.id INTO v_id;
    RETURN v_id;
END;
$$;

-- Find an API key by its public key_id before the tenant is known. Returns at most one row; the caller verifies the
-- secret hash in constant time and then switches to the returned organization's context.
CREATE FUNCTION aiep.find_api_key(p_key_id text)
RETURNS TABLE (
    id uuid, organization_id uuid, workspace_id uuid, owner_subject_id uuid, secret_hash bytea, environment text,
    permissions text[], expires_at timestamptz, revoked_at timestamptz)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = aiep, pg_temp
AS $$
    SELECT k.id, k.organization_id, k.workspace_id, k.owner_subject_id, k.secret_hash, k.environment,
           k.permissions, k.expires_at, k.revoked_at
    FROM aiep.api_keys k
    WHERE k.key_id = p_key_id;
$$;

-- Create an organization and its first Owner membership atomically. There is no tenant context before the
-- organization exists, so the function sets app.organization_id to the new id for its own inserts (the tenant policy
-- then applies normally) and restores the previous value afterwards. The owner is the authenticated subject in
-- app.subject_id, never a parameter. Reusing an existing organization id fails on the primary key before any
-- membership is written, so this cannot be used to join another tenant.
CREATE FUNCTION aiep.create_organization(p_organization_id uuid, p_name text, p_owner_membership_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = aiep, pg_temp
AS $$
DECLARE
    v_subject_id  uuid := nullif(current_setting('app.subject_id', true), '')::uuid;
    v_current_org text := nullif(current_setting('app.organization_id', true), '');
BEGIN
    IF v_subject_id IS NULL THEN
        RAISE EXCEPTION 'create_organization requires app.subject_id' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF v_current_org IS NOT NULL THEN
        RAISE EXCEPTION 'create_organization must run without an organization context'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    PERFORM set_config('app.organization_id', p_organization_id::text, true);

    INSERT INTO aiep.organizations (id, name, created_by) VALUES (p_organization_id, p_name, v_subject_id);
    INSERT INTO aiep.memberships (id, organization_id, subject_id, org_role, created_by)
    VALUES (p_owner_membership_id, p_organization_id, v_subject_id, 'Owner', v_subject_id);

    PERFORM set_config('app.organization_id', '', true);
END;
$$;

REVOKE ALL ON FUNCTION aiep.resolve_subject(uuid, text, text, text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION aiep.find_api_key(text)                          FROM PUBLIC;
REVOKE ALL ON FUNCTION aiep.create_organization(uuid, text, uuid)       FROM PUBLIC;
REVOKE ALL ON FUNCTION aiep.audit_events_append_only()                  FROM PUBLIC;
GRANT EXECUTE ON FUNCTION aiep.resolve_subject(uuid, text, text, text, text) TO aiep_api;
GRANT EXECUTE ON FUNCTION aiep.find_api_key(text)                          TO aiep_api;
GRANT EXECUTE ON FUNCTION aiep.create_organization(uuid, text, uuid)       TO aiep_api;
